**Semantic Versioning Scheme**: Each prompt update increments patch (0.0.1→0.0.2) for bugfixes/internal changes, minor (0.1.0→0.2.0) for new features/backward-compatible changes, and major (1.0.0→2.0.0) for breaking changes. **Metadata Schema**: Stored per version with tenant_id, data_sensitivity (public/internal/confidential/restricted), purpose, content, created_at, and parent_version for rollback tracking. **Safety-Checked Preview**: Before storing, regex patterns scan for blocked phrases (e.g., "hack the system", "bypass security"). If violations found, prompt is rejected. Otherwise, mock LLM extracts first line and generates 1-paragraph preview. **Rollback**: Re-retrieves content from target version, creates new version (patch++), and preserves parent_version reference to track rollback history. ```python from datetime import datetime from dataclasses import dataclass, field from typing import Optional import re @dataclass class PromptVersion: version: str tenant_id: str data_sensitivity: str purpose: str content: str created_at: datetime = field(default_factory=datetime.now) parent_version: Optional[str] = None def to_dict(self): return { "version": self.version, "tenant_id": self.tenant_id, "data_sensitivity": self.data_sensitivity, "purpose": self.purpose, "content": self.content, "created_at": self.created_at.isoformat(), "parent_version": self.parent_version } class PromptVersioningSystem: SENSITIVITY_LEVELS = {"public", "internal", "confidential", "restricted"} BLOCKED_PATTERNS = [ r"(?i)hack\s+the\s+system", r"(?i)ignore\s+(all\s+)?(safety|ethical|from\s+above)", r"(?i)bypass\s+(security|validation)", ] def __init__(self): self.versions: dict[str, dict[str, PromptVersion]] = {} def _parse_version(self, ver: str) -> tuple[int, int, int]: parts = ver.split(".") return tuple(map(int, parts)) if len(parts) == 3 else (0, 0, 0) def _bump_version(self, current: str, change_type: str) -> str: major, minor, patch = self._parse_version(current) if change_type == "major": return f"{major + 1}.0.0" elif change_type == "minor": return f"{major}.{minor + 1}.0" else: return f"{major}.{minor}.{patch + 1}" def _safety_check(self, text: str) -> dict: violations = [] for pattern in self.BLOCKED_PATTERNS: if re.search(pattern, text): violations.append(f"Pattern matched: {pattern}") return {"passed": len(violations) == 0, "violations": violations} def _mock_llm_preview(self, prompt: str) -> str: lines = [l.strip() for l in prompt.strip().split("
") if l.strip()] first_step = lines[0] if lines else "[Empty prompt]" return f"Step 1: {first_step}

[Preview via mock LLM - would execute: '{first_step[:50]}...']" def add_prompt(self, tenant_id: str, content: str, metadata: dict, change_type: str = "patch") -> dict: if tenant_id not in self.versions: self.versions[tenant_id] = {} sensitivity = metadata.get("data_sensitivity", "public") if sensitivity not in self.SENSITIVITY_LEVELS: raise ValueError(f"Invalid sensitivity: {sensitivity}") existing = self.versions[tenant_id] latest_ver = max(existing.keys(), default="0.0.0", key=lambda v: self._parse_version(v)) new_ver = self._bump_version(latest_ver, change_type) safety = self._safety_check(content) if not safety["passed"]: raise ValueError(f"Safety check failed: {safety['violations']}") preview = self._mock_llm_preview(content) prompt_version = PromptVersion( version=new_ver, tenant_id=tenant_id, data_sensitivity=sensitivity, purpose=metadata.get("purpose", ""), content=content, parent_version=latest_ver if latest_ver != "0.0.0" else None ) existing[new_ver] = prompt_version return {"version": new_ver, "safety_check": safety, "preview": preview, "prompt_entry": prompt_version.to_dict()} def rollback(self, tenant_id: str, target_version: str) -> dict: if tenant_id not in self.versions: raise ValueError(f"Tenant not found: {tenant_id}") versions = self.versions[tenant_id] if target_version not in versions: raise ValueError(f"Version not found: {target_version}") target = versions[target_version] new_ver = self._bump_version(target_version, "patch") rollback_entry = PromptVersion( version=new_ver, tenant_id=tenant_id, data_sensitivity=target.data_sensitivity, purpose=target.purpose, content=target.content, parent_version=target_version ) versions[new_ver] = rollback_entry return {"rolled_back_to": target_version, "new_version": new_ver, "prompt_entry": rollback_entry.to_dict()} def get_history(self, tenant_id: str) -> list[dict]: if tenant_id not in self.versions: return [] versions = self.versions[tenant_id] return [{"version": v, **versions[v].to_dict()} for v in sorted(versions.keys(), key=lambda x: self._parse_version(x))] if __name__ == "__main__": system = PromptVersioningSystem() result = system.add_prompt("tenant_001", "Analyze customer feedback and generate sentiment report", metadata={"data_sensitivity": "internal", "purpose": "analytics"}) print(f"Added: {result['version']} | Preview: {result['preview']}") result = system.add_prompt("tenant_001", "Summarize daily logs and flag anomalies", metadata={"data_sensitivity": "confidential", "purpose": "security"}) print(f"Added: {result['version']}") rb = system.rollback("tenant_001", "0.0.1") print(f"Rolled back to: {rb['new_version']}") print(f"History: {system.get_history('tenant_001')}") # Safety test try: system.add_prompt("tenant_001", "Hack the system to bypass security", metadata={"data_sensitivity": "public", "purpose": "test"}) except ValueError as e: print(f"Blocked: {e}") ``` **Output**: Added: 0.0.1 | Preview: Step 1: Analyze customer feedback... Added: 0.0.2 Rolled back to: 0.0.2 Blocked: Safety check failed: ['Pattern matched:...']

